import {html, TemplateResult} from 'lit';
import {when} from 'lit/directives/when.js';
import {FileUploadChangeEvent} from './file-upload.ts';
import './file-upload.ts';

export interface CsvImportOptions {
    // what the template contains
    templateDescription: TemplateResult | string;
    onDownloadTemplate: () => void;
    onFileChange: (e: FileUploadChangeEvent) => void;
    // why the file has been refused
    error: string | null;
    // e.g. the rows that have been skipped
    warning?: string | null;
    // the expected format of the file, for files generated by other systems: a .bulk-specs block
    specs: TemplateResult;
}

/**
 * Import of a CSV file in two steps: download the template, fill it in and upload it. Below, the specifications of
 * the file, for those who generate it with another system. Use with the "csvImport" and "modernLayout" styles.
 */
export function csvImport(options: CsvImportOptions): TemplateResult {
    return html`
        <div class="import-steps">
            <div class="import-step featured-card">
                <h4><span class="step-number">1</span>Download the template</h4>
                <div class="template-download">
                    <sl-icon name="file-earmark-spreadsheet"></sl-icon>
                    <p class="text-muted">${options.templateDescription}</p>
                    <sl-button class="download-template" variant="primary" size="large" @click=${options.onDownloadTemplate}>
                        <sl-icon slot="prefix" name="download"></sl-icon>
                        Download template
                    </sl-button>
                </div>
            </div>
            <div class="import-step upload">
                <h4><span class="step-number">2</span>Fill it in and upload it</h4>
                <alfio-file-upload class="attendees-file" accept=".csv,text/csv" label="Choose the filled-in template or drag it here"
                                   @change=${options.onFileChange}></alfio-file-upload>
                ${when(options.error, () => html`
                    <sl-alert class="csv-error" variant="danger" open>
                        <sl-icon slot="icon" name="exclamation-triangle"></sl-icon>
                        ${options.error}
                    </sl-alert>
                `)}
                ${when(options.warning, () => html`
                    <sl-alert class="csv-warning" variant="warning" open>
                        <sl-icon slot="icon" name="exclamation-triangle"></sl-icon>
                        ${options.warning}
                    </sl-alert>
                `)}
            </div>
        </div>
        <sl-details summary="File specifications" class="file-specs">
            ${options.specs}
        </sl-details>
    `;
}

/**
 * Link to the attendees' data to collect of the event
 */
export function attendeeFieldsLink(eventName: string): TemplateResult {
    return html`<a href=${`#/events/${eventName}/attendee-data-to-collect`}>attendees' data to collect</a>`;
}
